"use strict";const e=require("./api.js");exports.createCategory=async function(t){return e.request({path:"/categories",method:"POST",data:t})},exports.deleteCategory=async function(t){return e.request({path:`/categories/${t}`,method:"DELETE"})},exports.fetchCategories=async function(){return e.request({path:"/categories"})},exports.updateCategory=async function(t,r){return e.request({path:`/categories/${t}`,method:"PUT",data:r})};
